from dataclasses import dataclass

class Retryable(Exception): pass      # timeout, throttled, unavailable
class NonRetryable(Exception): pass  # invalid, auth, conflict

# LEVEL 4: data-access client — classify fast, retry once, no business logic
def db_read(key, deadline_ms):
    import random, time
    for attempt in (1, 2):  # exactly one retry, only for Retryable
        try:
            return _db_call(key, timeout_ms=min(800, deadline_ms))
        except Retryable:
            if attempt == 2 or deadline_ms < 200:
                raise  # let service decide fallback; do NOT loop forever
            time.sleep(0.02 * attempt + random.uniform(0, 0.02))  # jitter
        except NonRetryable:
            raise  # never retry: trade-off is one wasted call vs. poison loop

# LEVEL 3: service logic — one business fallback, with deadline awareness
def get_profile(user_id, deadline_ms):
    try:
        return db_read(user_id, deadline_ms)
    except Retryable:
        metrics.incr("profile.fallback.stale_cache")
        return stale_cache.get(user_id, degraded=True)  # authority to degrade
    except NonRetryable as e:
        raise_intentional_4xx(e)  # edge must NOT retry this

// LEVEL 2: edge — enforce budget, never re-retry classified errors
// Pseudocode for gateway filter: strip client retries, cap global attempts.
boolean allowRetry(Request req, Response upstream) {
    if (upstream.code() == 429 || upstream.code() == 503) {
        // Only retry safe, idempotent GETs, and only if budget remains.
        // Trade-off: we spend global capacity to smooth blips, but cap it.
        return req.isIdempotentGet()
            && retryBudget.hasTokens("edge")
            && !upstream.hasHeader("X-Handled-Fallback");
    }
    return false; // 4xx, validated business errors: fail fast, no retry
}
